import{_ as r,o as n,c as s,a3 as p}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/suchen-gruppenprozesse/gruppenprozesse-vermerke-merkmale-loeschen.png",h=JSON.parse('{"title":"Vermerke oder Merkmale gruppenweise löschen","description":"","frontmatter":{"title":"Vermerke oder Merkmale gruppenweise löschen","source_pageid":650,"source_revision":5334},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/vermerke-merkmale-loeschen-gruppenprozesse-allgemein.md","filePath":"schild3/suchen-gruppenprozesse/vermerke-merkmale-loeschen-gruppenprozesse-allgemein.md"}'),i={name:"schild3/suchen-gruppenprozesse/vermerke-merkmale-loeschen-gruppenprozesse-allgemein.md"};function a(m,e,o,t,u,d){return n(),s("div",null,[...e[0]||(e[0]=[p('<h1 id="vermerke-oder-merkmale-gruppenweise-loschen" tabindex="-1">Vermerke oder Merkmale gruppenweise löschen <a class="header-anchor" href="#vermerke-oder-merkmale-gruppenweise-loschen" aria-label="Permalink to &quot;Vermerke oder Merkmale gruppenweise löschen&quot;">​</a></h1><p>Wählen Sie eine Vermerkart oder ein Merkmal aus und entfernen Sie die zugehörigen Einträge bei der aktuellen Schülergruppe.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-vermerke-merkmale-loeschen.png"><img src="'+l+'" alt="Vermerke und Merkmale per Gruppenprozess löschen." loading="lazy"></a></p><p><em>Vermerke und Merkmale per Gruppenprozess löschen.</em></p><p>Dieser Gruppenprozess bietet Ihnen die Möglichkeit, bestimmte <em>Vermerke</em> oder <em>Merkmale</em> bei einer größeren Menge von Schülerinnen und Schülern gleichzeitig zu löschen.</p><p>Dazu ist zuerst auszuwählen, ob ein <em>Vermerk</em> oder ein <em>Merkmal</em> gelöscht werden soll.</p><p>Dann kann das jeweils zu löschende Element aus dem zweiten Dropdown-Menü ausgewählt werden, hierbei bietet SchILD die in den <em>Katalogen</em> definierten Vermerke beziehungsweise Merkmale an.</p><p>Abschließend muss die Ausführung des Gruppenprozesses über den Knopf <code>Prozess</code> angestoßen und die Sicherheitsfrage bestätigt werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Vermerke/Merkmale_l%C3%B6schen_(Gruppenprozesse_Allgemein)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5334.</p>',10)])])}const k=r(i,[["render",a]]);export{h as __pageData,k as default};
